// Generator for the Cherry keyboard module device table.
// Usage: node scripts/openrgb/port-cherry-devices.mjs <openrgb-root> <commit>
// Reads Controllers/CherryKeyboardController/CherryKeyboardControllerDetect.cpp
// and regenerates modules/cherry/src/devices_table.rs. Do not edit that file by hand.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = process.argv[2] ?? process.env.OPENRGB_ROOT ?? '../openrgb';
const commit = process.argv[3] ?? 'unknown';
const family = path.join(root, 'Controllers', 'CherryKeyboardController');
const detect = fs.readFileSync(path.join(family, 'CherryKeyboardControllerDetect.cpp'), 'utf8');
const all = fs
  .readdirSync(family, { recursive: true })
  .filter((f) => /\.(cpp|h)$/.test(f))
  .map((f) => fs.readFileSync(path.join(family, f), 'utf8'))
  .join('\n');
const constants = Object.fromEntries(
  [...all.matchAll(/#define\s+([A-Z][A-Z0-9_]+)\s+(0x[0-9A-Fa-f]+|\d+)/g)].map((m) => {
    let v = m[2].trim();
    let val = v.startsWith('0x') ? Number.parseInt(v, 16) : Number.parseInt(v, 10);
    return [m[1], val];
  }),
);
if (constants.CHERRY_KEYBOARD_VID == null) throw new Error('CHERRY_KEYBOARD_VID not found');
if (constants.CHERRY_KEYBOARD_USAGE_PAGE == null)
  throw new Error('CHERRY_KEYBOARD_USAGE_PAGE not found');
const n = (s) => (constants[s.trim()] ?? Number.parseInt(s.trim(), 16));
const rows = [];
for (const m of detect.matchAll(
  /REGISTER_HID_DETECTOR[A-Z_]*\s*\(\s*"([^"]+)"\s*,\s*([A-Za-z0-9_]+)\s*,\s*CHERRY_KEYBOARD_VID\s*,\s*([^,]+?)\s*,\s*([^,]+?)\s*,\s*([^,)]+?)\s*\)/g,
)) {
  const pid = n(m[3]);
  const iface = n(m[4]);
  const usagePage = n(m[5]);
  if (!Number.isFinite(pid) || !Number.isFinite(iface) || !Number.isFinite(usagePage)) {
    throw new Error(`unresolved detector expression: ${JSON.stringify([...m].slice(1, 6))}`);
  }
  rows.push({ name: m[1], handler: m[2], vid: constants.CHERRY_KEYBOARD_VID, pid, iface, usagePage });
}
if (rows.length === 0) throw new Error('no Cherry keyboard detectors parsed');
const out = path.join(process.cwd(), 'modules', 'cherry', 'src', 'devices_table.rs');
const lines = [
  '// SPDX-License-Identifier: GPL-2.0-or-later',
  `// Generated by scripts/openrgb/port-cherry-devices.mjs from OpenRGB ${commit}; do not edit.`,
  'use crate::table::Detector;',
  '',
  'pub const DETECTORS: &[Detector] = &[',
  ...rows.map(
    (d) =>
      `    Detector { name: ${JSON.stringify(d.name)}, handler: ${JSON.stringify(d.handler)}, vid: 0x${d.vid.toString(16).padStart(4, '0')}, pid: 0x${d.pid.toString(16).padStart(4, '0')}, interface: ${d.iface}, usage_page: 0x${d.usagePage.toString(16).padStart(4, '0')} },`,
  ),
  '];',
  '',
];
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, lines.join('\n'));
execFileSync(process.platform === 'win32' ? 'rustfmt.exe' : 'rustfmt', [out], { stdio: 'ignore' });
console.log(`generated ${rows.length} Cherry keyboard HID detectors`);